pub fn parse_duration(input: &str) -> Result<u64, String> {
    let split = input.len().saturating_sub(1);
    let (num, unit) = input.split_at(split);
    if num.is_empty() || !num.bytes().all(|b| b.is_ascii_digit()) {
        return Err(format!("invalid duration {input:?}: expected an integer followed by 's' or 'm'"));
    }
    let value: u64 = num
        .parse()
        .map_err(|_| format!("invalid duration {input:?}: number out of range"))?;
    match unit {
        "s" => Ok(value),
        "m" => value
            .checked_mul(60)
            .ok_or_else(|| format!("invalid duration {input:?}: too large")),
        _ => Err(format!("invalid duration {input:?}: unknown unit, expected 's' or 'm'")),
    }
}

